fn is_palindrome(s: &str) -> bool {
    // Filtrar solo caracteres alfanuméricos, convertir a minúsculas y comparar con reverso
    let chars: Vec<char> = s.chars()
        .filter(|c| c.is_alphanumeric())
        .map(|c| c.to_lowercase().chars().collect())  // convierte a vector de chars minúsculos
        .collect();

    let mut left = 0;
    let mut right = chars.len() - 1;
    while left < right {
        if chars[left] != chars[right] {
            return false;
        }
        left += 1;
        right -= 1;
    }
    true
}
```

