use std::collections::HashMap;
use std::cmp::Reverse;

fn word_freq(text: &str) -> Vec<(String, usize)> {
    let mut freq_map: HashMap<String, usize> = HashMap::new();

    // Extraer palabras: secuencias de caracteres alfabéticos (Unicode), convertidas a minúsculas
    let mut words = text.chars()
        .filter(|c| c.is_alphabetic())
        .flat_map(|c| Some(c))
        .collect::<Vec<_>>();

    // Dividir cada carácter en palabras (aquí asumimos que las palabras son secuencias de letras)
    // Como no se especifica separación, tomamos cada secuencia continua de letras como palabra.
    // Para simplificar: dividimos el texto en tokens que sean solo letras.
    let mut current_word = String::new();

    for c in text.chars() {
        if c.is_alphabetic() {
            current_word.push(c);
        } else {
            if !current_word.is_empty() {
                let word = current_word.to_lowercase();
                *freq_map.entry(word).or_insert(0) += 1;
                current_word.clear();
            }
        }
    }

    // Agregar la última palabra si existe
    if !current_word.is_empty() {
        let word = current_word.to_lowercase();
        *freq_map.entry(word).or_insert(0) += 1;
    }

    // Convertir el mapa en un vector ordenado: por frecuencia descendente, y en caso de empate alfabético ascendente.
    let mut result = Vec::new();
    for (word, count) in freq_map.iter() {
        result.push((word.clone(), *count));
    }

    // Ordenar: primero por frecuencia descendente (usando Reverse para ascender en orden natural),
    // luego alfabéticamente ascendente.
    result.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    result
}
```

