fn eval_rpn(expr: &str) -> Result<i64, String> {
    let tokens = expr.split_whitespace().collect::<Vec<&str>>();

    let mut stack: Vec<i64> = Vec::new();

    for token in tokens {
        match token {
            "+" => {
                if stack.len() < 2 {
                    return Err("Not enough operands".to_string());
                }
                let b = stack.pop().unwrap();
                let a = stack.pop().unwrap();
                stack.push(a + b);
            },
            "-" => {
                if stack.len() < 2 {
                    return Err("Not enough operands".to_string());
                }
                let b = stack.pop().unwrap();
                let a = stack.pop().unwrap();
                stack.push(a - b);
            },
            "*" => {
                if stack.len() < 2 {
                    return Err("Not enough operands".to_string());
                }
                let b = stack.pop().unwrap();
                let a = stack.pop().unwrap();
                stack.push(a * b);
            },
            "/" => {
                if stack.len() < 2 {
                    return Err("Not enough operands".to_string());
                }
                let b = stack.pop().unwrap();
                if b == 0 {
                    return Err("Division by zero".to_string());
                }
                let a = stack.pop().unwrap();
                stack.push(a / b);
            },
            num => {
                // Handle optional leading minus sign
                let s = token.to_string();
                if s.starts_with('-') {
                    let rest = &s[1..];
                    if rest.is_empty() {
                        return Err("Invalid number".to_string());
                    }
                    let num: i64 = rest.parse().map_err(|_| "Invalid number".to_string())?;
                    stack.push(num);
                } else {
                    let num: i64 = token.parse().map_err(|_| "Invalid number".to_string())?;
                    stack.push(num);
                }
            },
            _ => {
                return Err(format!("Invalid token: {}", token));
            }
        }
    }

    if stack.len() != 1 {
        if stack.len() > 1 {
            return Err("Too many values on stack".to_string());
        } else {
            return Err("Not enough values on stack".to_string());
        }
    }

    Ok(stack.pop().unwrap())
}
```

