use std::sync::Arc;
use std::thread;

fn parallel_sum(data: &[u64], threads: usize) -> u64 {
    if threads == 0 {
        threads = 1;
    }

    let chunk_size = (data.len() + threads - 1) / threads; // ceil division

    let mut handles = vec![];

    for i in 0..threads {
        let chunk: Vec<u64> = (i..(i + chunk_size)).take(data.len()).cloned().collect();
        let sum: u64 = chunk.iter().sum();

        let handle = thread::spawn(move || {
            // In case there are fewer elements than chunks, the remaining part is handled by taking min
            chunk.iter().sum()
        });

        handles.push(handle);
    }

    let mut total = 0u64;
    for handle in handles {
        total += handle.join().unwrap();
    }

    total
}
```

**Explicación:**
- Si `threads` es 0, se convierte a 1 para evitar hilos vacíos.
- Se calcula el tamaño de cada chunk usando división entera con redondeo hacia arriba (`(len + threads - 1) / threads`).
- Para cada hilo se crea un `Arc` implícito mediante el `move` closure (aquí no es necesario porque `chunk` es movido al hilo, pero en Rust 2021+ se puede usar directamente).
- Cada hilo suma los elementos de su chunk y devuelve el resultado.
- Se espera que el número de hilos sea igual o mayor que el número de chunks; si hay más hilos que elementos, los hilos adicionales recibirán un chunk vacío (suma 0).
- Se suman los resultados de todos los hilos para obtener la suma total.

