use std::fmt;

pub struct Fib {
    last: u64,
    current: u64,
}

impl Iterator for Fib {
    type Item = u64;

    fn next(&mut self) -> Option<u64> {
        if self.last == 0 {
            // First value is 0
            self.last = 0;
            self.current = 1;
            return Some(0);
        } else if self.last == 1 {
            // Second value is 1
            self.last = 1;
            self.current = 2;
            return Some(1);
        } else {
            // Compute next Fibonacci number without overflow
            let next = self.last + self.current;
            if next > u64::MAX {
                return None; // Stop when next would overflow u64
            }
            self.last = self.current;
            self.current = next;
            return Some(next);
        }
    }
}

impl Fib {
    fn new() -> Self {
        Fib { last: 0, current: 1 }
    }
}

fn fib() -> Fib {
    Fib::new()
}
