use std::collections::{BinaryHeap, HashMap};
use std::cmp::Reverse;

fn shortest_path(n: usize, edges: &[(usize, usize, u32)], src: usize, dst: usize) -> Option<u32> {
    // Build adjacency list
    let mut adj: HashMap<usize, Vec<(usize, u32)>> = HashMap::new();
    for &(u, v, w) in edges {
        adj.entry(u).or_insert_with(Vec::new);
        adj[u].push((v, w));
    }
    // Ensure all nodes exist in the map (even if no outgoing edges)
    for _ in 0..n {
        adj.entry(_).or_insert_with(Vec::new);
    }

    // Dijkstra's algorithm using a max-heap (BinaryHeap with Reverse)
    let mut dist: HashMap<usize, u32> = HashMap::new();
    let mut heap: BinaryHeap<Reverse<(u32, usize)>> = BinaryHeap::new(); // (distance, node)

    // Initialize distances
    dist.insert(src, 0);
    heap.push(Reverse((0, src)));

    while let Some(Reverse((current_dist, u))) = heap.pop() {
        // If we've already found a shorter path to u, skip
        if let Some(&dist_u) = dist.get(&u) {
            if current_dist > dist_u {
                continue;
            }
        }

        // Relax edges from u
        if let Some((neighbor, weight)) = adj.get(&u).and_then(|vec| vec.iter().find(|(v, _)| *v == neighbor))? {
            let new_dist = current_dist + weight;
            if let Some(&dist_n) = dist.get(&neighbor) {
                if new_dist < *dist_n {
                    dist.insert(neighbor, new_dist);
                    heap.push(Reverse((new_dist, neighbor)));
                }
            } else {
                dist.insert(neighbor, new_dist);
                heap.push(Reverse((new_dist, neighbor)));
            }
        }
    }

    // Return distance to dst if reachable
    dist.get(&dst).copied()
}
